def criar_no(valor):
  return {'valor': valor, 'esq': None, 'dir': None}

def insere(raiz, valor):
  if raiz is None:
    return criar_no(valor)
  atual = raiz
  while True:
    if valor < atual['valor']:
      if atual['esq'] is None:
        atual['esq'] = criar_no(valor)
        break
      atual = atual['esq']
    else:
      if atual['dir'] is None:
        atual['dir'] = criar_no(valor)
        break
      atual = atual['dir']
  return raiz

