class ponto:
  def __init__(self, x, y):
    self.x = x
    self.y = y

  def dist(self):
    return (self.x**2 + self.y**2)**0.5

  def __le__(self, outro):
    if self.dist() == outro.dist():
      if self.x == outro.x:
        return self.y <= outro.y
      else:
        return self.x <= outro.x
    else:
      return self.dist() <= outro.dist()

  def __str__(self):
    return f'{self.x} {self.y}'

