import copy

class Times():
  def __init__(self, times):
    self.times = times

  def busca_time(self, nome_time):
    for t in self.times:
      if(t.nome == nome_time):
        return t

  def __repr__(self):
    for t in self.times:
      print(t)
    return ''

  def hoare(self, lista):
    meio = len(lista)//2
    pivo = lista[meio]

    i, j = 0, len(lista)-1

    while True:
      while(lista[i] < pivo):
        i += 1
      while(lista[j] > pivo):
        j -= 1
      if(i < j):
        lista[i], lista[j] = lista[j], lista[i]
      else:
        return j

  def quick_sort(self, lista):
    nova_lista = copy.copy(lista)
    esq, dir = [], []
    if(len(nova_lista) > 1):
      pc = self.hoare(nova_lista)
      esq = self.quick_sort(nova_lista[:pc])
      dir = self.quick_sort(nova_lista[pc:])

      try:
        nova_lista = esq + dir
      except TypeError:
        try:
          nova_lista = esq
        except TyepError:
          nova_lista = dir

    return nova_lista

  def mostra_placar(self):
    self.times = self.quick_sort(self.times)

    for t in range(len(self.times)):
      print(f'{t+1} - {self.times[t]}')

