from collections import deque

def terminal_simulation(q, tasks):

  queue = deque(tasks)
  total_time = 0

  while queue:
    current_task = queue.popleft()

    if current_task <= q:
      total_time += q
      # current_time += q
    else:
      total_time += q
      # current_time += q
      remaining_time = current_task - q
      if remaining_time > 0:
        queue.append(remaining_time)

  total_time -= (q - current_task) if current_task <= q else 0

  return total_time

