import ast

def particiona_hoare(L, baixo, alto):
  pivo = L[(baixo+alto)//2]
  i = baixo - 1
  j = alto + 1
  while True:

    i += 1
    while L[i] < pivo:
      i += 1

    j -= 1
    while L[j] > pivo:
      j -= 1

