  else:
      no.dir = inserir(no.dir, v)
  return no

def pre_ordem(no):
  if not no:
    return
  yield no.valor
  yield from pre_ordem(no.esq)
  yield from pre_ordem(no.dir)

def in_ordem(no):
  if not no:
    return
  yield from in_ordem(no.esq)
  yield no.valor
  yield from in_ordem(no.dir)

def pos_ordem(no):
  if not no:
    return
  yield from pos_ordem(no.esq)
  yield from pos_ordem(no.dir)
  yield no.valor

