def max_heapify(A, n, i):

    left = 2 * i + 1
    right = 2 * i + 2
    largest = i


    if left < n and A[left] > A[largest]:
        largest = left


    if right < n and A[right] > A[largest]:
        largest = right


    if largest != i:
        A[i], A[largest] = A[largest], A[i]
        max_heapify(A, n, largest)


