void mergeSortNomeR(tipoDados v[], tipoDados aux[], int inicio, int fim) {
  int meio = (inicio + fim) / 2;
  int i = inicio, j = meio + 1;

  if(inicio < fim) {
    mergeSortNomeR(v, aux, inicio, meio);
    mergeSortNomeR(v, aux, meio + 1, fim);

    int k = inicio;
    while(i <= meio && j <= fim) {
