        aux[k] = v[i];
        i++;
      } else {
        aux[k] = v[j];
        j++;
      }
      k++;
    }

    while(i <= meio) {
      aux[k] = v[i];
      i++;
      k++;
    }
    while(j <= fim) {
      aux[k] = v[j];
      j++;
      k++;
    }

    for(k = inicio; k <= fim; k++) {
      v[k] = aux[k];
    }
  }

}

