// Função que implementa o algoritmo Bubble Sort
void bubbleSort(int vetor[], int tamanho) {
  for(int i=0; i< tamanho; i++){
    for(int j = 0 ; j < tamanho-i-1;j++){
      if(vetor[j]>vetor[j+1]){
        trocar(&vetor[j],&vetor[j+1]);
      }
    }
  }

}

