    if (i<= j){
      aux = v[i];
      v[i] = v[j];
      v[j] = aux;
      i++;
      j--;
      }
    }
  if(inicio<j){qSortR(v, inicio, j);inicio = i;}
   else{qSortR(v,i,fim); fim = j;} 
  }
}

void quickSortNome(tipoDados v[], unsigned tamVetor){
  qSortR(v, 0, tamVetor-1);
  insertSort(v,tamVetor);
}

