int eh_substring(char s[], char z[]) {

  int i, j;
  int ts = strlen(s);
  int tz = strlen(z);

  if (ts > tz){
    return 0;
  }

  for (i = 0; i <= tz - ts; i++) {
    for (j = 0; j < ts; j++) {
      if (z[i + j] != s[j]){
        break;
      }
    }
    if (j == ts) {
      return 1;
    }
  }
  return 0;
}

