    // Entrada dos elementos do vetor
    for (int i = 0; i < n; i++) {
        scanf("%d", &vetor[i]);
    }

    // Ordenando o vetor
    bubbleSort(vetor, n);

    // Imprimindo o vetor ordenado
    for (int i = 0; i < n; i++) {
        printf("%d ", vetor[i]);
    }

    return 0;
}

