  // Ex.: "abababd#ababd#" falharia sem um ponto de retorno.
  unsigned retorno;

  // Ler até atingir (null)
  while ((c = texto[t++]) != 0) {
    if (c == padrao[p]) {  
      if (p == 0)
        retorno = t;

      p++;
    } else if (padrao[p] == 0) {
      // O (null) do padrão foi atingido, logo, está contido no texto.
      return 1;
    } else {
      if (p != 0)
        t = retorno;

      p = 0;
    }
  }

  return padrao[p] == 0;
}

