void quickSortR (tipoPessoa v[],int inicio, int fim){
  int i, j;

  tipoPessoa pivot;
  tipoPessoa tmp;

  pivot = v[(inicio+fim)/2];
  i = inicio;
  j = fim;
  while(i<=j){
    while(v[i].altura > pivot.altura){i++;}
    while(v[j].altura < pivot.altura){j--;}

    if(i <= j){
      tmp = v[i];
      v[i] = v[j];
      v[j] = tmp;
      i++;
      j--;
    }
  }
