int buscaBinaria(int *v, int size, int chave){
  int inicio =0;
  int fim = size-1;

  while(inicio<= fim){
    int meio= inicio+ (fim- inicio)/2;

    if(v[meio] == chave){
      return 1;
    }
    else if(v[meio]< chave){
      inicio = meio+1;

    }
    else{
      fim = meio -1;
    }
    }

