void ordenar(int n, int *elementos){
  int i, j, chave;

  for(i = 1; i < n; i++){
    chave = elementos[i];
    j = i - 1;

    while(j >= 0 && elementos[j] > chave){
      if(elementos[j + 1] != elementos[j]){
        elementos[j + 1] = elementos[j];
        imprimir(n, elementos);
      }
      j--;
    }
    if(elementos[j + 1] != chave){
      elementos[j + 1] = chave;
      imprimir(n, elementos);
    }
  }
}
