  Lista *lista = lst_criar();

  for (int i = 0; i < N; i++)
  {
    Programa * p = ler_programa();
    lst_insere_fim(lista, p);
  }

  Programa *atual = lista->prim;

  int loop = Q;

  while (atual != NULL)
  {
    if (loop == 0)
    {
      loop = Q;
    }

    int retirar = 0;

    if (atual->tempo_restante <= loop)
