 */
Lista *cria_lista(void)
{
  Lista *nova = malloc(sizeof *nova);

  nova->ini = NULL;
  nova->fim = NULL;
  nova->tamanho = 0;

  return nova;
}


/* Insere um elemento (carta) na lista. Não se esqueça de atualizar
