 * carta no monte.
 */
void insere_fim(Lista *lista, int carta) {
  Nodo *novo = malloc(sizeof *novo);

  novo->carta = carta;
  novo->prox = NULL;
  novo->ant = lista->fim;

  if (lista->fim != NULL) 
    lista->fim->prox = novo;
  else 
    lista->ini = novo;

  lista->fim = novo;
  lista->tamanho++;
}



