  Nodo *removido = lista->ini;
  int valor = removido->carta;

  lista->ini = removido->prox;
  if (lista->ini != NULL) 
    lista->ini->ant = NULL;
  else 
    lista->fim = NULL;

  free(removido);
  lista->tamanho--;
  return valor;
}


