def bb(key, lis, ini, fim, lisRes):

  if ini > fim:
    return lisRes

  pivor = (ini + fim)//2
  lisRes.append(lis[pivor])

  if lis[pivor] == key:
    return lisRes
  elif lis[pivor] > key:
    return bb(key, lis, ini, pivor-1, lisRes)
  else:
    return bb(key, lis, pivor+1, fim, lisRes)


